  [417123] = { "I tuoi incantesimi Rinvigorimento e Ricrescita possono ora essere attivi su bersagli già sotto l'effetto del Rinvigorimento o della Ricrescita di un altro Druido.", nil, 0x98bc35ae, nil, "um" },
  [417135] = { "Aumenta del $N1% i danni inflitti dal tuo Uragano, che non ha più tempo di recupero e costa il $N2% di mana in meno.", nil, 0xa6f14cbc, nil, "um" },
  [417141] = { { "|CFFFFFFFFRichiede ⟦Cat Form=Forma Felina⟧, ⟦Bear Form=Forma d'Orso⟧, Dire Bear Form|R\nLa tua abilità Morso Primordiale colpisce fino a $N1 bersagli e non ha più tempo di recupero, e la probabilità di critico delle tue abilità che generano punti combo aumenta del $N2%. Rimuove gli effetti di paura e ne conferisce l'immunità per tutta la durata. Dura $D1.", "|CFFFF2020Richiede ⟦Cat Form=Forma Felina⟧, ⟦Bear Form=Forma d'Orso⟧, Dire Bear Form|R\nLa tua abilità Morso Primordiale colpisce fino a $N1 bersagli e non ha più tempo di recupero, e la probabilità di critico delle tue abilità che generano punti combo aumenta del $N2%. Rimuove gli effetti di paura e ne conferisce l'immunità per tutta la durata. Dura $D1.", shape = { "3/1", "3/1" }, key = { "09e26ee72ad66b11", "190b7d0a449dfe1d" } }, "Le abilità che generano punti combo ottengono il $N1% di probabilità di critico in più.\nMorso Primordiale colpisce fino a $N2 bersagli e non ha tempo di recupero.\nImmune agli effetti di paura.", 0x67700812, 0xa6f78b53, "uu" },
  [417145] = { "Colpire un bersaglio con Lacerazione, Spazzata o Zampata ha il $N1% di probabilità di azzerare il tempo di recupero di Mangle (Bear) e di conferire $N2 rabbia. Colpire un bersaglio con Mangle (Cat) o Artigliata ha il $N3% di probabilità di azzerare il tempo di recupero di ⟦Tiger's Fury=Furia della Tigre⟧.", nil, 0x5b32606e, nil, "um" },
  [417146] = { nil, "Nell'Efflorescenza di un Druido.", nil, 0xba44b6a4, "mu" },
  [417147] = { "Cura di $N2 salute tutti i membri del gruppo o dell'incursione entro $N1 m dall'area selezionata ogni $D1 per $D2.", "Cura ogni $D1 di $N2 tutti i membri del gruppo del bersaglio della tua Guarigione Immediata che si trovano nella tua Efflorescenza.", 0x77ef4186, 0x8e2d4e7c, "uu" },
  [417148] = { "Cura di $N2 salute tutti i membri del gruppo entro $N1 m dal bersaglio.", nil, 0x8ee8859e, nil, "um" },
  [417149] = { "La tua Guarigione Immediata ora provoca anche Efflorescenza, che cura di $N2 salute tutti i membri del gruppo entro $N1 m dal punto in cui si trova il bersaglio di Guarigione Immediata ogni $D1 per $D2.", nil, 0xfa6947b4, nil, "um" },
  [417157] = { "Scaglia impetuose energie stellari che infliggono $N1 danni da arcano e aumentano del $N3% i danni dei tuoi prossimi $N2 lanci di Fuoco Stellare per $D1.\n\nCometa Arcana beneficia della maggior parte dei talenti e degli effetti che si attivano con Ira Silvana o Fuoco Stellare o ne beneficiano, e li attiva.", "I tuoi prossimi $N1 lanci di Fuoco Stellare infliggono il $N2% di danni in più.", 0x5b236c3f, 0x624d73d8, "uu" },
  [417159] = { "Ti cura istantaneamente del $N1% della tua salute massima. Utilizzabile in tutte le forme.", nil, 0x28428f72, nil, "um" },
  [417192] = { nil, "Inginocchiati davanti al Loa per ricevere la sua saggezza.", nil, 0x731b2e2d, "mu" },
  [417315] = { nil, nil, 0x5c0f8e85, nil, "em" },
  [417316] = { nil, "La meditazione ha espanso la tua mente, dandoti la lucidità per apprendere nuovi incantesimi dalle Memorie sparse per il mondo.", nil, 0x0f1e11e9, "mu" },
  [417345] = { "Equipaggia un oggetto per la testa con una runa incisa per attivare un'abilità in questo spazio.", nil, 0x407fa9b3, nil, "um" },
  [417346] = { "Equipaggia un oggetto per i polsi con una runa incisa per attivare un'abilità in questo spazio.", nil, 0xbb892d16, nil, "um" },
  [417347] = { "Equipaggia un oggetto per la schiena con una runa incisa per attivare un'abilità in questo spazio.", nil, 0x39b2b0bc, nil, "um" },
  [417348] = { "Equipaggia un oggetto per le spalle con una runa incisa per attivare un'abilità in questo spazio.", nil, 0x6b8649ed, nil, "um" },
  [417433] = { "Dissotterra il tesoro nel punto segnato", nil, 0xcb9fbb49, nil, "um" },
  [417434] = { "Combina con altri $N1 pezzi per ottenere la mappa completa.", nil, 0xdcc7f5cf, nil, "um" },
  [417440] = { "Colpisce tutti i nemici vicini, infliggendo $N1 danni da sanguinamento e ulteriori $N2 danni da sanguinamento in $D1. Se applicato in ⟦Bear Form=Forma d'Orso⟧, questo effetto si cumula fino a $N4 volte.", nil, 0x9fe9051f, nil, "um" },
  [417441] = { nil, "$N1 danni da sanguinamento subiti ogni $N2 s.", nil, 0xbabe73bb, "mu" },
  [417448] = { "Colpisce tutti i nemici vicini, infliggendo $N1 danni da sanguinamento e ulteriori $N2 danni da sanguinamento in $D1. Fornisce $N4 punti combo.", "$N1 danni da sanguinamento subiti ogni $D1.", 0x53483d55, 0x84eecd00, "uu" },
  [417453] = { "Ottieni diverse nuove abilità demoniache: Disrupt, Demon Charge, Demonic Howl e Assalto Infernale.\n\n$I1\nSoffoca il nemico con un'ondata di energia d'ombra che infligge $N1 danni, interrompe il lancio d'incantesimi e impedisce di lanciare incantesimi di quella scuola per $D1.\n\n$I2\nCarica un nemico e lo stordisce per $D2. Non utilizzabile in combattimento.\n\n$I3\nCostringe tutti i nemici vicini a concentrare gli attacchi su di te per $D3.\n\n$I4\nBalza in aria e piomba su tutti i nemici entro $N5 m dall'area bersaglio, infliggendo $N6 danni da ombra e stordendoli per $D4.", nil, 0x52f94238, nil, "um" },
  [417463] = { nil, "La morte sfiorata ti rivela temporaneamente il regno spettrale.", nil, 0xaa93f5d0, "mu" },
  [417627] = { "Bevi l'elisir nel cimitero di Tanaris.", nil, 0x95316d5e, nil, "um" },
  [417743] = { "Crea documenti falsi che accusano la ⟦Scarlet Crusade=Crociata Scarlatta⟧ di tramare contro l'⟦Alliance=Alleanza⟧. Richiede l'occorrente per scrivere che si trova nel municipio di Brill.", nil, 0xd6127412, nil, "um" },
  [417803] = { nil, "I tuoi occhi sono colmi di fiamma spettrale, che ti concede la vista oltre il velo mortale.", nil, 0x75c01edf, "mu" },
  [417856] = { nil, "Prega la Luce per ricevere saggezza", nil, 0x4fa0d13e, "mu" },
})
